package io.github.diodeme.ji.acp.v1;

import io.github.diodeme.ji.error.ErrorCode;
import java.io.IOException;
import java.util.Map;

/** Structured connection failure raised when the ACP client cannot drain output. */
final class SlowConsumerException extends IOException {
    private static final long serialVersionUID = 1L;
    private final Map<String, String> parameters;

    SlowConsumerException(long maximumBytes, int maximumFrames) {
        super(ErrorCode.PROTOCOL_SLOW_CONSUMER.code()
                + " bufferBytes=" + maximumBytes + " bufferFrames=" + maximumFrames);
        parameters = Map.of(
                "bufferBytes", Long.toString(maximumBytes),
                "bufferFrames", Integer.toString(maximumFrames));
    }

    ErrorCode code() { return ErrorCode.PROTOCOL_SLOW_CONSUMER; }
    Map<String, String> parameters() { return parameters; }
}
